{
  "category_edits": [
    {
      "category": "learning_objective",
      "rationale": "Across all four datasets, blend the existing weighted BPR objective with 10% unweighted pairwise softplus loss. This may improve candidate ordering while preserving the existing sampled negatives, scores, GRU architecture, inference, and training settings.",
      "edits": [
        {
          "find": "    pairwise_loss = torch.nn.functional.softplus(valid_neg - valid_pos)\n    return (weights * pairwise_loss).sum()",
          "replace": "    pairwise_loss = torch.nn.functional.softplus(valid_neg - valid_pos)\n    existing_loss = (weights * pairwise_loss).sum()\n    return 0.9 * existing_loss + 0.1 * pairwise_loss.mean()"
        }
      ]
    }
  ],
  "change_summary": "Apply the specified 90/10 loss blend to each category's single GRU model using existing valid positive-negative pairs. No predictor changes are required."
}
